effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  float l = gmLum(src.rgb / a);
  l = mix(l, 1.0 - l, invert);
  vec2 o = vec2(amountX, amountY) * (l - 0.5) * 2.0 * mixAmt;
  gl_FragColor = texture2DCv(inputImg.texture, uv + o);
}
